# -------------------- COOLDOWN CHECK --------------------
def check_cooldown(ctx):
    user_id = ctx.author.id
    cmd = ctx.command.name
    now = time.time()

    # Owner bypass
    if user_id in (BOT_OWNER_ID, PERMANENT_OWNER):
        return True

    last_used = cooldowns[user_id].get(cmd, 0)
    cd = command_cooldowns.get(cmd, DEFAULT_COOLDOWN)

    if now - last_used < cd:
        remaining = round(cd - (now - last_used), 1)
        return remaining   # returns remaining seconds

    cooldowns[user_id][cmd] = now
    return True

# -------------------- DECORATOR --------------------
def cooldown():
    async def predicate(ctx):
        result = check_cooldown(ctx)
        if result is not True:
            await ctx.send(f"⏳ Cooldown: **{result}s** remaining", delete_after=3)
            return False
        return True
    return commands.check(predicate)
 

ACCESS_FILE = "phantomtest1231.json"

def load_allowed():
    if os.path.exists(ACCESS_FILE):
        try:
            with open(ACCESS_FILE, "r") as f:
                data = json.load(f)
                return set(data)
        except Exception as e:
            print(f"[Access] Failed to load file: {e}")
            return {BOT_OWNER_ID, PERMANENT_OWNER}
    return {BOT_OWNER_ID, PERMANENT_OWNER}

def save_allowed():
    try:
        with open(ACCESS_FILE, "w") as f:
            json.dump(list(allowed_ids), f, indent=2)
    except Exception as e:
        print(f"[Access] Failed to save file: {e}")

# Load on start
