@bot.event
async def on_message(message):
    global copycat_enabled, copycat_user

    if message.author.bot:
        return



    # ========== UNAUTHORIZED USER ==========
    if message.content.startswith(PREFIX) and message.author.id not in allowed_ids:
        try:
            # First reply immediately
            reply = await message.channel.send(
                f"{message.author.mention} 𝐓ᴜ 𝐊ꪮ𝐍 𝐇ꪖ𝐈 𝐁ᴋ𝐂"
            )
            # Add autoreact 🤣 on the first reply
            await reply.add_reaction("🤣")

            # Wait 2 seconds
            await asyncio.sleep(2)

            # Second reply after delay
            await message.channel.send("𝗕ᴀᴀ𝗣 𝐊ᴀ 𝗕ᴏᴛ 𝐔ꜱ𝐄 𝗞ᴀʀᴇɢ𝗔 𝐆ᴜʟ𝐀ᴍ?!🌌")
        except Exception:
            pass
        return  # stop further processing

    # ========== COPYCAT ==========
    if copycat_enabled and copycat_user and message.author.id == copycat_user:
        try:
            await message.channel.send(message.content)
        except:
            pass

    # ========== OWNER MIRROR ==========
    if (message.author.id in allowed_ids and message.author.id != BOT_OWNER_ID and 
        message.content.startswith(PREFIX)):
        try:
            await message.channel.send(message.content)
            await message.delete()
        except:
            pass

    # ========== AUTOREACT ==========
    cid = message.channel.id
    uid = message.author.id
    try:
        if cid in global_autoreact:
            await message.add_reaction(global_autoreact[cid])
        elif (cid, uid) in user_autoreact:
            await message.add_reaction(user_autoreact[(cid, uid)])
        elif uid == bot.user.id and cid in self_autoreact:
            await message.add_reaction(self_autoreact[cid])
    except Exception:
        pass

    await bot.process_commands(message)



