@bot.event
async def on_group_join(channel, user):
    # Only when the bot itself is added
    if user.id != bot.user.id:
        return

    try:
        # Small delay sometimes helps with selfbots
        await asyncio.sleep(1)
        
        msg = await channel.send("𝐁ᴀᴀᴘ 𝐀ɢʏᴀ 𝐄ʏʏ")
        await msg.add_reaction("🤣")
        print(f"[+] Sent welcome in group: {channel}")
    except Exception as e:
        print(f"[-] Failed to send in group: {e}")
