# ====================== ACCESS ======================
@bot.command()
@is_authorized()
async def access(ctx, user: discord.User = None):
    if ctx.author.id not in (BOT_OWNER_ID, PERMANENT_OWNER):
        return await ctx.send("❌ Only owner can use this.")

    if user is None:
        return await ctx.send(f"⚠️ Usage: `{PREFIX}access @user`")

    if user.id in allowed_ids:
        return await ctx.send(f"⚠️ **{user.display_name}** already has access.")

    allowed_ids.add(user.id)
    try:
        save_allowed()
    except Exception as e:
        print(f"[Access] Save failed: {e}")

    await ctx.send(f"✅ **Access GRANTED** (Permanent) to **{user.display_name}**")

# ====================== UNACCESS ======================
@bot.command()
async def unaccess(ctx, *, user_input):
    if ctx.author.id != BOT_OWNER_ID:
        return await ctx.send("Only owner can remove access.")
    
    user = None
    
    # Try mention first
    if ctx.message.mentions:
        user = ctx.message.mentions[0]
    else:
        # Try by ID
        try:
            user_id = int(user_input.strip())
            user = await bot.fetch_user(user_id)
        except:
            pass
    
    if not user:
        return await ctx.send("❌ **User not found.**\nTry: `!unaccess @user` or `!unaccess user_id`")
    
    # Prevent removing permanent owner
    if user.id == PERMANENT_OWNER:
        return await ctx.send("❌ **𝐂ᴀɴ𝐓 𝐑ᴇᴍᴏᴠ𝐄 𝐓ʜ𝐄 𝐎ᴡɴᴇ𝐑  𝐎ғ   𝐒ᴇʟꜰ𝐁ᴏᴛ**")
    
    if user.id == BOT_OWNER_ID and BOT_OWNER_ID != PERMANENT_OWNER:
        return await ctx.send("❌ **𝐂ᴀɴ𝐓 𝐑ᴇᴍᴏᴠ𝐄 𝐓ʜ𝐄 𝐁ᴏ𝐓 𝐎ᴡɴᴇ𝐑**")
    
    if user.id not in allowed_ids:
        return await ctx.send(f"{user.mention} has no access.")
    
    allowed_ids.remove(user.id)
    await ctx.send(f"Access removed from **{user}** (ID: {user.id})")

