@bot.command()
@is_authorized()
@cooldown()
async def domainexp(ctx, user:discord.User):
    if is_protected(text):
        return await ctx.send("**❌ PROTECTED NAME DETECTED**")
    key = (ctx.channel.id, user.id)

    if key in domain_tasks and not domain_tasks[key].done():
        return await ctx.send("⚠️ Domain Expansion is already active on this user.")

    await ctx.send(f"🌀 **Domain Expansion activated on {user.mention}**")

    async def domain_loop():
        while True:
            try:
                msg = random.choice(domain_messages)
                content = f"{user.mention}\n{msg}"
                await safe_send(ctx.channel, content)
                await asyncio.sleep(1.2)  # adjust speed if needed
            except asyncio.CancelledError:
                break
            except Exception:
                await asyncio.sleep(1.5)

    task = asyncio.create_task(domain_loop())
    domain_tasks[key] = task


@bot.command()
@is_authorized()
@cooldown()
async def domainexpstop(ctx, user:discord.User = None):
    if user:
        key = (ctx.channel.id, user.id)
        if key in domain_tasks and not domain_tasks[key].done():
            domain_tasks[key].cancel()
            del domain_tasks[key]
            await ctx.send(f"🛑 Domain Expansion stopped on {user.mention}")
        else:
            await ctx.send("⚠️ No Domain Expansion running on this user.")
    else:
        # stop all in this channel
        stopped = 0
        for key in list(domain_tasks.keys()):
            if key[0] == ctx.channel.id:
                domain_tasks[key].cancel()
                del domain_tasks[key]
                stopped += 1
        await ctx.send(f"🛑 Stopped **{stopped}** Domain Expansions in this channel.")
