# ====================== BLOCKTEXT ======================

@bot.command()
@is_authorized()
@cooldown()
async def blocktext(ctx, *, cmd_part: str):
    # Limit to 8 characters
    text = cmd_part.strip()[:8]

    block_map = {
        "A": "██\n█ █\n███\n█ █\n█ █",
        "B": "██\n█ █\n██\n█ █\n██",
        "C": " ██\n█\n█\n█\n ██",
        "D": "██\n█ █\n█ █\n█ █\n██",
        "E": "███\n█\n██\n█\n███",
        "F": "███\n█\n██\n█\n█",
        "G": " ██\n█\n█ ██\n█  █\n ██",
        "H": "█ █\n█ █\n███\n█ █\n█ █",
        "I": "███\n █\n █\n █\n███",
        "J": "  █\n  █\n  █\n█ █\n ██",
        "K": "█ █\n█ █\n██\n█ █\n█ █",
        "L": "█\n█\n█\n█\n███",
        "M": "█ █\n███\n█ █\n█ █\n█ █",
        "N": "█ █\n██ █\n█ █\n█ █\n█ █",
        "O": " █\n█ █\n█ █\n█ █\n █",
        "P": "██\n█ █\n██\n█\n█",
        "R": "██\n█ █\n██\n█ █\n█ █",
        "S": " ██\n█\n ██\n  █\n██",
        "T": "███\n █\n █\n █\n █",
        "U": "█ █\n█ █\n█ █\n█ █\n ██",
        "W": "█ █\n█ █\n███\n███\n█ █",
        "X": "█ █\n █\n █\n █\n█ █",
        "Y": "█ █\n █\n █\n █\n █",
        "Z": "███\n  █\n █\n█\n███",
    }

    # Prepare 5 lines
    lines = ["", "", "", "", ""]
    for ch in text.upper():
        rows = block_map.get(ch, "?").split("\n")
        for i in range(5):
            lines[i] += (rows[i] if i < len(rows) else "") + "  "

    # Send the block text
    await ctx.send("\n".join(lines))


