@bot.command()
@is_authorized()
@cooldown()
async def clear(ctx, amount: int = 100):
    deleted = 0
    async for msg in ctx.channel.history(limit=amount):
        if msg.author.id == bot.user.id:
            try:
                await msg.delete()
                deleted += 1
                await asyncio.sleep(0.3)
            except:
                pass
    await ctx.send(f"✅ Cleared **{deleted}** of your messages.", delete_after=3)


