@bot.command()
@is_authorized()
@cooldown()
async def snipe(ctx, amount: int = 5):
    channel_id = ctx.channel.id
    
    if channel_id not in sniped_messages or len(sniped_messages[channel_id]) == 0:
        return await ctx.send("❌ **No deleted messages found.**")

    # Clamp amount between 1–10
    amount = max(1, min(amount, 10))
    messages = sniped_messages[channel_id][:amount]

    # Header
    result = f"**🔫 𝐒𝐍𝐈𝐏𝐄𝐃 𝐌𝐄𝐒𝐒𝐀𝐆𝐄𝐒** (`{len(messages)}`)\n"
    result += "━━━━━━━━━━━━━━━━━━━━━━━━━━\n"

    # Format each sniped message
    for i, msg in enumerate(messages, 1):
        author = msg.get("author", "Unknown")
        time = msg.get("time", "Unknown")
        content = msg.get("content") or "*[No text / Embed / Attachment]*"

        # Truncate long content
        if len(content) > 150:
            content = content[:150] + "..."

        result += f"**{i}.** 👤 `{author}` • 🕒 `{time}`\n"
        result += f"╰ 💬 {content}\n\n"

    # Footer
    result += "━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
    result += f"⚡ Requested by: {ctx.author.mention}"

    await ctx.send(result)


@bot.command()
@is_authorized()
@cooldown()
async def stealth(ctx, mode: str = None):
    """Toggle Stealth Mode on/off
    Example: !stealth on / !stealth of"""
    global stealth_mode

    if mode is None:
        status = "ON ✅" if stealth_mode else "OFF ❌"
        return await ctx.send(f"**Stealth Mode:** {status}")

    mode = mode.lower()
    if mode in ["on", "true", "1", "enable"]:
        stealth_mode = True
        await ctx.send("✅ **Stealth Mode Enabled**\nCommands will now be auto‑deleted.")
    elif mode in ["off", "false", "0", "disable"]:
        stealth_mode = False
        await ctx.send("❌ **Stealth Mode Disabled**")
    else:
        await ctx.send("⚠️ Use `!stealth on` or `!stealth off`")
	

