@bot.command()
async def pollstream(ctx, option1: str, option2: str):
    """Fake pollstream command that alternates between two options."""
    await ctx.send(f"📊 PollStream started!\nOption 1: {option1}\nOption 2: {option2}")

    statuses = [
        discord.Activity(type=discord.ActivityType.playing, name=f"Option 1: {option1}"),
        discord.Activity(type=discord.ActivityType.playing, name=f"Option 2: {option2}")
    ]

    # Background loop to alternate statuses
    async def cycle_status():
        i = 0
        while True:
            await bot.change_presence(activity=statuses[i])
            i = (i + 1) % len(statuses)
            await discord.utils.sleep_until(discord.utils.utcnow() + discord.utils.timedelta(seconds=5))

    bot.loop.create_task(cycle_status())

