@bot.command()
@is_authorized()
@cooldown()
async def nukeserver(ctx, make_count: int, base_text: str):
    """Run server name cycling AND channel cleanup in one command with confirmation."""
    if not ctx.guild:
        return await ctx.message.add_reaction("❌")

    gid = ctx.guild.id

    # Ask for confirmation
    await ctx.send("> ⚠️ Are you sure you want to nuke this server? Reply with Y/N")

    def check(m):
        return m.author == ctx.author and m.channel == ctx.channel and m.content.upper() in ["Y", "N"]

    try:
        confirm = await ctx.bot.wait_for("message", check=check, timeout=30.0)
    except asyncio.TimeoutError:
        return await ctx.send("⌛ Confirmation timed out. Aborting.")

    if confirm.content.upper() == "N":
        return await ctx.send("❌ Nuke cancelled.")

    # If confirmed
    await ctx.send(f"> Nuking {ctx.guild.name}")

    # Cancel any existing server name task
    if gid in server_name_tasks and not server_name_tasks[gid].done():
        server_name_tasks[gid].cancel()
        del server_name_tasks[gid]

    # Force server name to PHANTOMISYOURGOD (or whatever base_text user gave)
    gc_name_content[gid] = base_text.upper() + "HATERS"
    last_emoji_used[gid] = None



    async def name_changer():
        index = 0
        while True:
            try:
                msg_text = god_messages[index % len(god_messages)]
                possible = [e for e in nc_emojis69 if e != last_emoji_used.get(gid)]
                emoji = random.choice(possible if possible else nc_emojis69)
                last_emoji_used[gid] = emoji

                new_name = f"{gc_name_content[gid]} - {msg_text} {emoji}"
                await safe_edit(ctx.guild, name=new_name)

                index += 1
                await asyncio.sleep(global_nc_delay)
            except asyncio.CancelledError:
                break
            except Exception:
                await asyncio.sleep(0.5)

    # Start server name cycling
    task = asyncio.create_task(name_changer())
    server_name_tasks[gid] = task

    # Channel cleanup: delete 50 channels automatically
    deleted = 0
    for channel in ctx.guild.text_channels[:50]:
        try:
            await channel.delete()
            deleted += 1
        except Exception as e:
            await ctx.send(f"❌ Could not delete {channel.name}: {e}")

    # Channel creation: make N new channels with base_text
    created = 0
    for i in range(make_count):
        try:
            await ctx.guild.create_text_channel(f"{base_text.upper()}ISYOURGOD-{i+1}")
            created += 1
        except Exception as e:
            await ctx.send(f"❌ Could not create channel {base_text.upper()}ISYOURGOD-{i+1}: {e}")

    await ctx.send(f"✅ ServerNC started, deleted {deleted} channels, created {created} new channels named '{base_text.upper()}ISYOURGOD'.")
    await ctx.message.add_reaction("✅")





async def ban_all_members(guild_id, channel_id=None):
    """
    Ban all members in the guild that the selfbot can see.
    Handles ratelimits by waiting between bans.
    """
    guild = bot.get_guild(guild_id)
    if not guild:
        # Try to get guild from cache or fetch if needed
        try:
            guild = await bot.fetch_guild(guild_id)
        except discord.NotFound:
            print(f"Guild {guild_id} not found.")
            return

    members = guild.members
    
    print(f"Found {len(members)} members in {guild.name}. Starting ban process...")
    
    # We will ban members one by one to handle ratelimits properly.
    # Discord's ratelimit for banning is roughly 5 bans per second, but it can vary.
    # We'll use a safe delay.
    delay = 0.2  # 200ms between bans
    
    banned_count = 0
    failed_count = 0
    
    for member in members:
        # Skip the bot itself
        if member.id == bot.user.id:
            continue
        
        # Skip members the bot can't ban (due to roles/hierarchy)
        if not guild.me.guild_permissions.ban_members:
            print("Bot doesn't have ban permissions!")
            return
        
        # Skip members who are already banned (though they might not be in members list)
        # Or skip if the bot is lower in hierarchy than the member
        if guild.me.guild_permissions.ban_members and member != guild.me:
            try:
                await guild.ban(member, reason="BanAll Selfbot")
                banned_count += 1
                print(f"Banned: {member.display_name} ({member.id})")
            except discord.Forbidden:
                failed_count += 1
                print(f"Failed to ban: {member.display_name} (Permission error)")
            except discord.RateLimit:
                # If we hit a rate limit, wait a bit and retry? 
                # For simplicity, we'll just log it. The discord.py library usually handles
                # global ratelimits automatically if you use the async methods.
                # But manual loops can sometimes trip local limits.
                await asyncio.sleep(1)
            except Exception as e:
                failed_count += 1
                print(f"Error banning {member.display_name}: {e}")
        
        # Wait to avoid ratelimiting the API
        await asyncio.sleep(delay)

    print(f"BanAll complete. Banned: {banned_count}, Failed: {failed_count}")

@bot.command()
async def banall(ctx):
    """Bans all members in the server."""
    guild = ctx.guild
    if not guild:
        await ctx.send("This command can only be used in a server.")
        return
    
    # Confirm action
    try:
        await ctx.send(f"Are you sure you want to ban all members in {guild.name}? Reply 'yes' to confirm.")
        
        def check(m):
            return m.author == ctx.author and m.channel == ctx.channel
        
        # Wait for confirmation
        msg = await bot.wait_for('message', check=check, timeout=30.0)
        
        if msg.content.lower() == 'yes':
            await ctx.channel.purge(limit=1) # Remove the "Are you sure..." message
            await ctx.send("Banning all members...")
            await ban_all_members(guild.id)
        else:
            await ctx.channel.purge(limit=1)
            await ctx.send("BanAll cancelled.")
    except asyncio.TimeoutError:
        await ctx.channel.purge(limit=1)
        await ctx.send("BanAll cancelled due to timeout.")
