# Global dictionaries to track spam state
spam_tasks = {}
spam_running = {}

@bot.command(name="spam")
@is_authorized()
@cooldown()
async def spam(ctx, *, text: str = ""):
    if not text:
        return await ctx.send("❌ Usage: `!spam <text>`")

    cid = ctx.channel.id
    stop_spam(cid)
    spam_running[cid] = True

    async def run():
        idx = 0
        emojis = ["😺","😸","😹","😻","😼","😽","🙀","😿","😾","🐱"]
        while spam_running.get(cid, False):
            try:
                if _token_is_hot(bot_index):
                    await asyncio.sleep(1.0 + _jitter())
                    continue
                lines = []
                em = emojis[idx % len(emojis)]
                idx += 1
                base = f"{text} {em}"
                while True:
                    nxt = lines + [base]
                    if len("\n".join(nxt)) > 1980:
                        break
                    lines = nxt
                content = _fill("\n".join(lines) if lines else base)
                await safe_send(ctx.channel, content)
            except asyncio.CancelledError:
                break
            except Exception:
                pass
            await asyncio.sleep(RL_FLOOR + current_delay + _jitter())

    task = asyncio.ensure_future(run())
    spam_tasks[cid] = task
    await ctx.send(f"> ⚡ **SPAM STARTED** → `{text[:60]}`")


