@bot.command(name="Fuga")
@is_authorized()
async def Fuga(ctx, *, text: str = None):
    cid = ctx.channel.id

    # If already running → stop it
    if cid in eng_spam_tasks and not eng_spam_tasks[cid].done():
        eng_spam_tasks[cid].cancel()
        del eng_spam_tasks[cid]
        return await ctx.send("🛑 English spam stopped.")

    await ctx.message.add_reaction("✅")

    async def spammer():
        index = 0
        count = 1
        try:
            # Send once at start
            await ctx.send("https://klipy.com/gifs/anime-goated")

            while True:
                msg = english_msgs[index % len(english_msgs)]

                if text:
                    content = f"{text} {msg}\n > {count:03d}"
                else:
                    content = f"{msg}\n > {count:03d}"

                index += 1
                count += 1

                await safe_send(ctx.channel, content)

                # ✅ Yield control so cancellation can be processed
                await asyncio.sleep(eng_spam_delay)

        except asyncio.CancelledError:
            # ✅ Exit gracefully when stop command cancels the task
            await ctx.send("🛑 Fuga spam stopped.")
            return
        except Exception as e:
            print(f"Fuga spam error: {e}")
            await asyncio.sleep(0.3)

    task = asyncio.create_task(spammer())
    eng_spam_tasks[cid] = task


