# ====================== GHOSTTYPE ======================

@bot.command()
async def ghosttype(ctx, count: int, *, msg: str):
    """Send & delete quickly."""
    key = ctx.channel.id

    async def ghost_loop():
        try:
            for _ in range(count):
                m = await ctx.send(msg)
                await asyncio.sleep(ghost_speed)
                await m.delete()
        except asyncio.CancelledError:
            return
        except Exception as e:
            await ctx.send(f"❌ Error: {e}")

    # cancel existing ghost loop if running
    if key in ghost_tasks:
        ghost_tasks[key].cancel()

    task = asyncio.create_task(ghost_loop())
    ghost_tasks[key] = task
    await ctx.send(f"👻 Ghosttype started ({count}x) with speed {ghost_speed}s.")

@bot.command()
async def stopghosttype(ctx):
    """Stop ghost typing."""
    key = ctx.channel.id
    task = ghost_tasks.get(key)
    if task:
        task.cancel()
        del ghost_tasks[key]
        await ctx.send("🛑 Ghosttype stopped.")
    else:
        await ctx.send("❌ No ghosttype running here.")

