# ====================== WARN SPAM ======================
@bot.command()
@is_authorized()
@cooldown()
async def warn(ctx, user: discord.User = None, amount: int = 10):
    if is_protected(text):
        return await ctx.send("**❌ PROTECTED NAME DETECTED**")
    if user is None:
        return await ctx.send("⚠️ Usage: `!warn @user [amount]`")

    if amount < 1 or amount > 50:
        amount = 10

    cid = ctx.channel.id
    key = f"{cid}_{user.id}"

    if key in warn_tasks and not warn_tasks[key].done():
        warn_tasks[key].cancel()
        del warn_tasks[key]


    async def warn_loop():
        try:
            for i in range(amount):
                msg = random.choice(warn_messages)
                content = f"{user.mention} {msg}".replace("@", "＠")
                await safe_send(ctx.channel, content)
                await asyncio.sleep(warn_delay)
        except asyncio.CancelledError:
            pass
        except Exception:
            pass
        finally:
            if key in warn_tasks:
                del warn_tasks[key]

    task = asyncio.create_task(warn_loop())
    warn_tasks[key] = task

@bot.command()
@is_authorized()
@cooldown()
async def stopwarn(ctx):
    stopped = 0
    for key, task in list(warn_tasks.items()):
        if not task.done():
            task.cancel()
            stopped += 1
        del warn_tasks[key]
    await ctx.send(f"🛑 Stopped **{stopped}** warn tasks.")
