@bot.command()
@is_authorized()
@cooldown()
async def dmspam(ctx, user: discord.User):

    user_id = user.id
    if user_id in dm_spam_tasks and not dm_spam_tasks[user_id].done():
        dm_spam_tasks[user_id].cancel()
        del dm_spam_tasks[user_id]
        await ctx.message.add_reaction("⏹️")
        return

    try:
        dm_channel = await user.create_dm()
    except:
        return await ctx.send("Cannot DM this user.")

    messages = [
        "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <🤍>", "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <🩶>", "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <🖤>",
        "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <🤎>", "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <💜>", "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <🩵>",
        "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <💙>", "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <💚>", "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <💛>",
        "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <🧡>", "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <🩷>", "𝐇ɪᴊ𝐃ᴀ 𝐇ᴀ𝐈 𝐓ᴜ <❤️>",
    ]

    async def dm_spammer():
        msg_index = 0
        while True:
            try:
                content = messages[msg_index]
                if autofiller_enabled and autofiller_char:
                    filler_len = max(0, 1999 - len(content) - 1)
                    if filler_len > 0:
                        content = autofiller_char * filler_len + " " + content
                await safe_send(dm_channel, content)
                msg_index = (msg_index + 1) % len(messages)
            except asyncio.CancelledError:
                break
            except Exception:
                await asyncio.sleep(0.6)
            await asyncio.sleep(0)

    task = asyncio.create_task(dm_spammer())
    dm_spam_tasks[user_id] = task
    await ctx.message.add_reaction("✅")


