@bot.command()
@is_authorized()
@cooldown()
async def target(ctx, user: discord.User):
    user_id = user.id
    channel_id = ctx.channel.id
    key = (channel_id, user_id)

    # Stop if already running
    if key in target_tasks and not target_tasks[key].done():
        target_tasks[key].cancel()
        del target_tasks[key]

    target_last_replied[key] = set()

    async def target_reply():
        try:
            while True:
                def check(m):
                    return (m.author.id == user_id and 
                            m.channel.id == channel_id and 
                            m.author != bot.user)

                msg = await bot.wait_for('message', check=check)

                # Prevent replying twice to the same message
                if msg.id in target_last_replied.get(key, set()):
                    continue

                target_last_replied[key].add(msg.id)

                # Pick random message
                reply_text = random.choice(target_messages)

                try:
                    await msg.reply(reply_text, mention_author=False)
                except:
                    await safe_send(msg.channel, reply_text)

                await asyncio.sleep(0.35)

        except asyncio.CancelledError:
            pass
        except Exception as e:
            print(f"Target error: {e}")

    task = asyncio.create_task(target_reply())
    target_tasks[key] = task

    await ctx.message.add_reaction("✅")
    await ctx.send(f"✅ **𝐓ᴀʀɢᴇ𝐓 𝐒ᴛᴀ𝐑ᴛᴇ𝐃** **𝐎ɴ** **{user}**")


@bot.command()
@is_authorized()
@cooldown()
async def targetstop(ctx, user: discord.User):
    user_id = user.id
    channel_id = ctx.channel.id
    key = (channel_id, user_id)

    if key in target_tasks and not target_tasks[key].done():
        try:
            target_tasks[key].cancel()
            await asyncio.sleep(0.3)
            del target_tasks[key]
            target_last_replied.pop(key, None)
            
            await ctx.message.add_reaction("✅")
            await ctx.send(f"✅ **𝐓ᴀʀɢᴇ𝐓 𝐒ᴜᴄᴄᴇꜱꜱꜰᴜʟʟʏ 𝐒ᴛᴏᴘᴘᴇ𝐃** **𝐅ᴏʀ** **{user}**")
        except Exception:
            await ctx.send("❌ **𝐄ʀʀᴏʀ 𝐖ʜɪʟᴇ 𝐒ᴛᴏᴘᴘɪɴɢ**")
    else:
        await ctx.message.add_reaction("❌")
        await ctx.send(f"❌ **𝐍ᴏ 𝐀ᴄᴛɪᴠᴇ 𝐓ᴀʀɢᴇ𝐓 𝐅ᴏᴜɴᴅ** **𝐅ᴏʀ** **{user}** **𝐈ɴ 𝐓ʜɪꜱ 𝐂ʜᴀɴɴᴇʟ**")



# ====================== ULTIMATE PIC CHANGER ======================
# ====================== PFP COMMANDS ======================

@bot.command()
@is_authorized()
async def pfp(ctx):
    """Change your PFP by replying to an image"""
    if not ctx.message.reference:
        return await ctx.send("❌ **Reply** to an image to set it as PFP.")

    try:
        replied = await ctx.channel.fetch_message(ctx.message.reference.message_id)
        if not replied.attachments:
            return await ctx.send("❌ No image found in the replied message.")

        image_url = replied.attachments[0].url
        async with aiohttp.ClientSession() as session:
            async with session.get(image_url) as resp:
                if resp.status == 200:
                    img_bytes = await resp.read()
                    await bot.user.edit(avatar=img_bytes)
                    await ctx.send("✅ **PFP changed successfully!**")
                else:
                    await ctx.send("❌ Failed to download image.")
    except Exception as e:
        await ctx.send(f"❌ Error: `{e}`")


@bot.command()
@is_authorized()
async def pfploop(ctx):
    """Start rotating saved PFPs"""
    global pfp_loop_task, pfp_loop_active

    if len(pfp_slots) < 2:
        return await ctx.send("❌ At least **2 slots** save karo pehle (`!set1` to `!set10` style).")

    if pfp_loop_active:
        return await ctx.send("⚠️ PFP loop already running. Use `!stoppfp` first.")

    pfp_loop_active = True
    await ctx.send(f"🔄 **PFP Loop started** with {len(pfp_slots)} slots | Delay: {pfp_delay}s")

    async def loop():
        slots = sorted(pfp_slots.keys())
        index = 0
        while pfp_loop_active:
            try:
                slot = slots[index % len(slots)]
                await bot.user.edit(avatar=pfp_slots[slot])
                index += 1
                await asyncio.sleep(pfp_delay)
            except discord.HTTPException as e:
                if e.status == 429:
                    retry = getattr(e, "retry_after", 5)
                    await asyncio.sleep(retry + 1)
                else:
                    await asyncio.sleep(3)
            except Exception:
                await asyncio.sleep(3)

    pfp_loop_task = asyncio.create_task(loop())


@bot.command()
@is_authorized()
async def stoppfp(ctx):
    """Stop PFP rotation"""
    global pfp_loop_active, pfp_loop_task

    pfp_loop_active = False
    if pfp_loop_task and not pfp_loop_task.done():
        pfp_loop_task.cancel()
    await ctx.send("🛑 **PFP Loop stopped.**")


@bot.command()
@is_authorized()
async def pfpdelay(ctx, sec: float):
    """Set PFP loop delay"""
    global pfp_delay
    pfp_delay = max(0.0, sec)
    await ctx.send(f"⏱️ PFP delay set to **{pfp_delay}s**")


@bot.command()
@is_authorized()
async def spampfp(ctx, count: int = 5):
    """Spam random saved PFPs in chat"""
    if not pfp_slots:
        return await ctx.send("❌ No PFPs saved.")

    count = min(max(1, count), 15)
    await ctx.send(f"📸 Spamming **{count}** PFPs...")

    for i in range(count):
        try:
            slot = random.choice(list(pfp_slots.keys()))
            file = discord.File(fp=io.BytesIO(pfp_slots[slot]), filename=f"pfp_{slot}.png")
            await ctx.send(file=file)
            await asyncio.sleep(1.2)
        except Exception:
            await asyncio.sleep(1)


@bot.command()
@is_authorized()
async def listslots(ctx):
    """Show saved PFP slots"""
    if not pfp_slots:
        return await ctx.send("📭 No slots saved.")

    msg = "**📸 Saved PFP Slots:**\n"
    for slot in sorted(pfp_slots.keys()):
        msg += f"• Slot `{slot}` ✅\n"
    await ctx.send(msg)


@bot.command()
@is_authorized()
async def clearslot(ctx, slot: int):
    """Clear a specific slot (1-10)"""
    if slot < 1 or slot > 10:
        return await ctx.send("❌ Slot number 1 se 10 ke beech hona chahiye.")

    if slot in pfp_slots:
        del pfp_slots[slot]
        await ctx.send(f"🗑️ Slot **{slot}** cleared.")
    else:
        await ctx.send(f"❌ Slot **{slot}** empty hai.")


@bot.command()
@is_authorized()
async def copypfp(ctx, user: discord.User, slot: int = None):
    """Copy user's PFP (optionally save to slot)"""
    try:
        avatar_bytes = await user.display_avatar.read()

        if slot:
            if slot < 1 or slot > 10:
                return await ctx.send("❌ Slot 1-10 only.")
            pfp_slots[slot] = avatar_bytes
            await ctx.send(f"✅ **{user.name}** .")
        else:
            await bot.user.edit(avatar=avatar_bytes)
            await ctx.send(f"✅ **{user.name}** ")

        # Also set as current PFP
        await bot.user.edit(avatar=avatar_bytes)

    except Exception as e:
        await ctx.send(f"❌ Failed: `{e}`")


