async def save_to_slot(ctx, slot_num: int):
    if not ctx.message.reference:
        return await ctx.send("❌ **Reply** to an image to save it.")

    try:
        replied_msg = await ctx.channel.fetch_message(ctx.message.reference.message_id)

        if not replied_msg.attachments:
            return await ctx.send("❌ No image found in the replied message.")

        image_url = replied_msg.attachments[0].url

        async with aiohttp.ClientSession() as session:
            async with session.get(image_url) as resp:
                if resp.status == 200:
                    img_bytes = await resp.read()
                    
                    # Save for both systems
                    pic_state["slots"][slot_num] = img_bytes
                    pfp_slots[slot_num] = img_bytes
                    
                    await ctx.send(f"✅ Image saved to **Slot {slot_num}**")
                else:
                    await ctx.send("❌ Failed to download image.")
    except Exception as e:
        await ctx.send(f"❌ Error: {str(e)[:200]}")
