@bot.command()
@is_authorized()
@cooldown()
async def startpic(ctx):
    if not isinstance(ctx.channel, discord.GroupChannel):
        return await ctx.send("❌ **[ULTIMATE]** Only works in Group Chats.")

    if len(pic_state["slots"]) < 2:
        return await ctx.send("❌ **[ULTIMATE]** Save at least 2 images first.")

    pic_state["active"] = True
    await ctx.send(f":rocket: **[ULTIMATE]** Starting rotation with {len(pic_state['slots'])} images...")

    async def rotation_loop():
        sorted_slots = sorted(pic_state["slots"].keys())
        while pic_state["active"]:
            for slot in sorted_slots:
                if not pic_state["active"]:
                    break
                try:
                    await ctx.channel.edit(icon=pic_state["slots"][slot])
                    await asyncio.sleep(pic_state["delay"] or 1.0)
                except discord.HTTPException as e:
                    if e.status == 429:
                        retry = getattr(e, "retry_after", 5)
                        jitter = random.uniform(0.2, 1.0)
                        await asyncio.sleep(retry + jitter)
                    else:
                        await asyncio.sleep(2)
                except Exception:
                    await asyncio.sleep(2)

    if pic_state.get("current_task") and not pic_state["current_task"].done():
        pic_state["current_task"].cancel()

    pic_state["current_task"] = asyncio.create_task(rotation_loop())

@bot.command()
@is_authorized()
async def stopall(ctx):
    stopped = 0

    # All task dictionaries
    task_groups = [
        autoreact_tasks,
        spam_tasks,
        spam_tasks2,
        spam3_tasks,          # fixed name
        eng_spam_tasks,
        custom_spam_tasks,
        warn_tasks,
        ghost_tasks,
        poll_spam_tasks,
        domain_tasks,
        slide_tasks,
        target_tasks,         # ← added
        dm_spam_tasks,
        foodnc_tasks,
        fontnc_tasks,         # ← added
        gc_name_tasks,
        gcnc_tasks,
        hindinc_tasks,
        server_name_tasks,
        gcmaker_tasks,
        gc_tasks,
        kentospam_tasks,
    ]

    for group in task_groups:
        for key, task in list(group.items()):
            try:
                if task and not task.done():
                    task.cancel()
                    stopped += 1
                del group[key]
            except:
                pass

    # Reset feature flags
    global autofiller_enabled, autofiller_char, copycat_enabled, copycat_user
    global autoreact_enabled, autoreact_users, auto_do_enabled

    autofiller_enabled = False
    autofiller_char = ""
    copycat_enabled = False
    copycat_user = None
    autoreact_enabled = False
    autoreact_users = {}
    auto_do_enabled = False

    # Clear autoreact dictionaries
    global_autoreact.clear()
    user_autoreact.clear()
    self_autoreact.clear()

    # Stop picture rotation
    try:
        pic_state["active"] = False
        if pic_state.get("current_task") and not pic_state["current_task"].done():
            pic_state["current_task"].cancel()
            stopped += 1
    except:
        pass

    # Clear target & slide replied tracking
    try:
        last_replied.clear()
        target_last_replied.clear()
    except:
        pass
	
    await ctx.send(f"🛑 **Stopped {stopped} tasks and reset all features!**")

